/**
 * World currency pegs, mapped.
 *
 * Universe: IMF AREAER 2023 de facto classes, updated through Sep 2026
 * (Bulgaria euro Jan 2026, Curacao XCG Mar 2025, Iraq correspondent-bank
 * 2025, Nigeria / Egypt / Ethiopia / Bolivia exits). 5y realized vol =
 * annualized stdev of daily log returns vs the listed anchor, Yahoo daily,
 * Sep 2021–Sep 2026, 252-day year. vq "c" is clean; "n" is robust after
 * dropping |daily move| > 0.5%; "z" is legal 1:1 / dollarization; "x" is
 * missing (unlisted or peg-broken). Sources: IMF AREAER 2023, IMF Article
 * IV country consultations, ECB / Fed / ECB-BNB press releases for the
 * 2024–2026 changes. Geometry below is reused from the source canvas;
 * see `world-currency-pegs.canvas.tsx` for the upstream provenance.
 */

export type Kind = "Hard" | "Soft" | "Dirty" | "Crawl" | "Other";
export type Status = "Intact" | "Stressed" | "Exited" | "Floating union";
export type Entity = "Sovereign" | "Territory" | "Bloc";
export type Vq = "c" | "n" | "z" | "x";

export type Peg = {
  c: string;
  iso: string;
  kind: Kind;
  imf: string;
  anc: string;
  rate: string;
  flex: string;
  since: string;
  yrs: number | null;
  move: string;
  how: string;
  vol: number | null;
  vq: Vq;
  rng: string;
  status: Status;
  dual: boolean;
  ent: Entity;
  region: string;
};

export type MapFeat = { n: string; d: string; x: number; y: number; a: number };
export type MapExtra = { kind: Kind; anc: string; rate: string };
export type MapPoint = { n: string; x: number; y: number };
export type MapRegion = { id: string; label: string; vb: string };


